#include "stdafx.h"

// =============================================================================
//  (th4) Chinese (Simplified) localization -- LANG_CHI = 8
//
//  ENCODING: GB2312, written as \xNN escapes so the file stays pure ASCII and is
//  byte-exact regardless of what editor opens it. GB2312 is 2 bytes/char:
//  lead 0xB0..0xF7, trail 0xA1..0xFE -- both ABOVE the colour-control window
//  0x80..0x8B, so colour codes need no change (the same free ride CP1251 gets).
//
//  C2022 TRAP: MSVC reads \xNN greedily, so an escape followed by an ASCII hex
//  digit fuses into a 3-digit escape. Any such join is broken with "" -- e.g.
//  "\xB5\xD8""abc" not "\xB5\xD8abc". Never hand-edit these literals; edit
//  chi/ui_chi.py and re-emit.
//
//  FONTS: the CJK glyphs ship in TH4loc_chi.mor (mounted at 8900 only when
//  language == CHI). Each CEL keeps frames 0..255 = the original base font
//  (Latin pixel-identical) and appends GB2312 CJK at frames 256..7023, so
//  letterID = 257 + gbIndex. Cells are built at the STOCK widths (small 13,
//  mid 22, big 46), so no blitter change was needed. ASCII keeps the stock
//  English font tables -- LANG_CHI deliberately has no case in the font-script
//  switch in Localization.cpp.
//
//  Unknown ids fall through to *n = 0 -> xlate() returns the English string, so
//  the build is playable at every step.
// =============================================================================

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	// (th4) MUST stay in sync with the master enum in Localization.cpp -- the ids are
	// array indices shared across TUs. Appended last, so ids 0..14 are unchanged and the
	// other loc files need no edit: Localization.cpp loops to ITS OVL_STR_COUNT and
	// their GetStrTable() returns {0,0} for the unknown id, keeping the nominative.
	OVL_WARP_OBL,
	OVL_STR_COUNT
};

enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

struct UiStr { const char* en; const char* chi; };
struct IdxStr { int idx; const char* chi; };

