		case TraitId::Scissor: return "\xC3\xBB\xD3\xD0\xB6\xDC\xC5\xC6\xBF\xC9\xB9\xA9\xB8\xF1\xB5\xB2";
		case TraitId::Capitalist: return "\xB3\xF5\xCA\xBC\xBD\xF0\xB1\xD2\xD1\xB0\xD5\xD2\xBD\xB5\xB5\xCD""33%";
