const UiStr* CHI_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:           *n = countRows(CHI_Ui);          return CHI_Ui;
		case OVL_BASE_ITEM:    *n = countRows(CHI_BaseItem);    return CHI_BaseItem;
		case OVL_UNIQUE_ITEM:  *n = countRows(CHI_UniqueItem);  return CHI_UniqueItem;
		case OVL_ELEMENT:      *n = countRows(CHI_Element);     return CHI_Element;
		case OVL_SPICIES:      *n = countRows(CHI_Spicies);     return CHI_Spicies;
		case OVL_SPELL:        *n = countRows(CHI_Spell);       return CHI_Spell;
		case OVL_SPELL_NOM:    *n = countRows(CHI_SpellNom);    return CHI_SpellNom;
		case OVL_WARP:         *n = countRows(CHI_Warp);        return CHI_Warp;
		case OVL_AFFIX_PREFIX: *n = countRows(CHI_AffixPrefix); return CHI_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = countRows(CHI_AffixSuffix); return CHI_AffixSuffix;
		case OVL_MENU:         *n = countRows(CHI_Menu);        return CHI_Menu;
		case OVL_ICEAGE:       *n = countRows(CHI_IceAge);      return CHI_IceAge;
		case OVL_PERK_NAME:    *n = countRows(CHI_PerkName);    return CHI_PerkName;
		case OVL_PERK_DESC:    *n = countRows(CHI_PerkDesc);    return CHI_PerkDesc;
		case OVL_BASE_NAME2:   *n = countRows(CHI_BaseName2);   return CHI_BaseName2;
	}
	*n = 0; return 0;      // unknown id -> English fallback
}

// ---------------------------------------------------------------------------
//  NPC speech (Mid font, medtexts.cel). Index-keyed: index == the position in
//  Speeches[] in structs_speech.cpp, whose English is NEVER edited. Reached via
