const IdxStr* CHI_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_ONSCREEN:     *n = countRows(CHI_OnScreen);    return CHI_OnScreen;
		case OVL_SPEECH:       *n = countRows(CHI_Speech);      return CHI_Speech;
		case OVL_QUEST:        *n = countRows(CHI_Quest);       return CHI_Quest;
	}
	*n = 0; return 0;      // any table not listed above -> English fallback
}
